rong><small>{{ $pickup['packages'] }} paquete(s) · {{ $pickup['weight'] }} kg</small>@if($pickup['from'])<small>{{ \Illuminate\Support\Carbon::parse($pickup['from'])->format('d/m/Y H:i') }} - {{ \Illuminate\Support\Carbon::parse($pickup['to'])->format('H:i') }}</small>@endif @if($pickup['error'])<small class="text-danger">{{ $pickup['error'] }}</small>@endif</div></article>@empty<p class="text-secondary">No hay recolecciones registradas.</p>@endforelse</div></div></div></div></div>
