@push('scripts')
<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('#quick-shipping-form'),cp=document.querySelector('#quick-postal'),msg=document.querySelector('#quick-message'),results=document.querySelector('#quick-results'),empty=document.querySelector('#quick-empty'),button=document.querySelector('#quick-quote-button'),say=(t,k='danger')=>{msg.className=`alert alert-${k} mt-3 mb-0`;msg.textContent=t};document.querySelector('#quick-postal-search')?.addEventListener('click',async()=>{if(!/^\d{5}$/.test(cp.value))return say('Escribe un CP valido.');try{const r=await fetch(`{{ url('/admin/shipments/postal-code') }}/${cp.value}`,{headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok)throw Error(j.message);document.querySelector('#quick-state').value=j.places[0].state;document.querySelector('#quick-city').value=j.places[0].city;document.querySelector('#quick-neighborhood').innerHTML=j.places.map(p=>`<option>${p.neighborhood}</option>`).join('');say('Ubicacion encontrada.','success')}catch(e){say(e.message)}});form?.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;say('Consultando Skydropx...','info');try{const r=await fetch(@json(route('admin.shipments.quick-quote.calculate')),{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok)throw Error(j.message||Object.values(j.errors||{})[0]?.[0]);empty.hidden=true;results.innerHTML=`<h2 class="h4">${j.rates.length} tarifas</h2><div class="shipping-rates">${j.rates.map(x=>`<article class="shipping-rate"><i class="bi bi-truck"></i><span><strong>${x.carrier}</strong><small>${x.service} · ${x.days||'?'} dias</small></span><b>$${Number(x.price).toFixed(2)}</b></article>`).join('')}</div>`;say('Cotizacion lista.','success')}catch(e){say(e.message)}finally{button.disabled=false}});const cov=document.querySelector('#pickup-coverage'),sel=document.querySelector('#pickup-shipment'),out=document.querySelector('#pickup-coverage-result');cov?.addEventListener('click',async()=>{if(!sel.value)return;cov.disabled=true;try{const u=new URL(@json(route('admin.shipments.pickup-coverage')),location.origin);u.searchParams.set('shipment_id',sel.value);const r=await fetch(u,{headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok)throw Error(j.message);out.className='alert alert-success small';out.textContent='Esta guia tiene cobertura. Selecciona una fecha valida de recoleccion.'}catch(e){out.className='alert alert-danger small';out.textContent=e.message}finally{cov.disabled=false}});document.querySelector('#pickup-form')?.addEventListener('submit',e=>{if(!confirm('¿Enviar esta solicitud de recoleccion a Skydropx?'))e.preventDefault()})});</script>
@endpush
